<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { assetCategoryLabels, assetBusinessLevelLabels, assetStatutoryCategoryLabels, ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import { catalogKinds, catalogMetadataFields, type CatalogEntry } from './discovery'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>();const base=workspacePath(props.workspace.slug)+'/catalog';const entries=ref<CatalogEntry[]>([]);const kind=ref('');const search=ref('');const error=ref('');const notice=ref('');const busy=ref(false);const truncated=ref(false);const selected=ref<CatalogEntry|null>(null);const metadata=ref<Record<string,string>>({});const history=ref<{revision:number;origin:string;metadata:unknown;createdAt:string}[]>([]);const cmdb=ref('');const showImport=ref(false);const editable=computed(()=>['owner','operator'].includes(props.workspace.role));const summary=ref<Record<string,number>>({});
function failed(e:unknown){if(e instanceof ApiError&&e.status===401){emit('sessionExpired');return}error.value=describeError(e)}
async function load(){busy.value=true;error.value='';try{const [r,s]=await Promise.all([request<{items:CatalogEntry[];truncated:boolean}>(base+'?'+new URLSearchParams({kind:kind.value,q:search.value})),request<Record<string,number>>(base+'/summary')]);entries.value=r.items;truncated.value=r.truncated;summary.value=s}catch(e){failed(e)}finally{busy.value=false}}
async function choose(entry:CatalogEntry){selected.value=entry;metadata.value={};for(const k of Object.keys(catalogMetadataFields)){metadata.value[k]=String(entry.confirmedMetadata[k]??entry.metadata[k]??'')}try{const r=await request<{items:typeof history.value}>(base+'/'+entry.id+'/history');history.value=r.items}catch(e){failed(e)}}
async function save(){if(!selected.value)return;busy.value=true;try{await request(base+'/'+selected.value.id+'/metadata',{method:'PUT',body:JSON.stringify({revision:selected.value.revision,metadata:metadata.value})});notice.value='业务属性已确认，后续来源冲突将单独显示。';const id=selected.value.id;await load();const entry=entries.value.find(e=>e.id===id);if(entry)await choose(entry)}catch(e){failed(e)}finally{busy.value=false}}
async function importCMDB(){busy.value=true;try{const payload=JSON.parse(cmdb.value);const r=await request<{imported:number;replayed:boolean;conflicts:number}>(base+'/cmdb',{method:'POST',body:JSON.stringify(payload)});notice.value=`导入 ${r.imported} 项，${r.conflicts} 项属性冲突${r.replayed?'（幂等重放）':''}。`;showImport.value=false;await load()}catch(e){failed(e)}finally{busy.value=false}}
function example(){cmdb.value=JSON.stringify({version:1,source:'enterprise-cmdb',batchId:'2026-11-11-001',records:[{sourceRef:'business-order',parentRef:'',kind:'business',name:'订单业务',system:'commerce',metadata:{ownerTeam:'业务运营',businessOrganization:'零售事业部',region:'中国',sharingRecipients:'内部财务',retention:'按经确认的业务保留规则执行'}},{sourceRef:'order-app',parentRef:'business-order',kind:'application',name:'订单应用',system:'commerce',metadata:{business:'订单业务',ownerTeam:'研发团队'}}]},null,2)}
onMounted(()=>void load())
</script>
<template><section class="catalog-page"><header class="page-header"><div><p class="eyebrow">DAI · 资产目录</p><h1>业务与数据资产目录</h1><p>业务、应用、数据库、表与字段使用同一资产身份。自动观察、人工确认与来源冲突分别留档。</p></div><button v-if="editable" class="button primary" @click="showImport=!showImport">导入 CMDB</button></header><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div class="catalog-stats"><span>目录资产 <strong>{{summary.entries||0}}</strong></span><span>表 / 集合 <strong>{{summary.tables||0}}</strong></span><span>字段 / 路径 <strong>{{summary.fields||0}}</strong></span><span>当前来源 <strong>{{summary.currentSources||0}} / {{summary.sources||0}}</strong></span><span>规则证据 <strong>{{summary.ruleHits||0}}</strong></span></div>
<form v-if="showImport" class="catalog-card" @submit.prevent="importCMDB"><h2>标准 CMDB JSON</h2><p>新对象用 sourceRef 幂等合并。为已采集目录补充业务属性时，在记录中填写该行的 assetId；跨工作区资产会拒绝。已人工确认的不同属性保留为冲突。</p><button type="button" class="button" @click="example">填入示例</button><textarea v-model="cmdb" rows="15" required aria-label="CMDB JSON"></textarea><button class="button primary" :disabled="busy">导入</button></form>
<form class="catalog-filters" @submit.prevent="load"><label>对象类型<select v-model="kind"><option value="">全部</option><option v-for="(label,k) in catalogKinds" :key="k" :value="k">{{label}}</option></select></label><label>搜索<input v-model="search" maxlength="160" placeholder="名称、来源、库表或字段"></label><button class="button" :disabled="busy">查询</button></form>
<p v-if="truncated">当前展示最多1000项，请缩小筛选范围。</p><div class="table-scroll"><table><thead><tr><th>资产 / 身份</th><th>层次 / 路径</th><th>来源 / 覆盖</th><th>业务归属</th><th>分类</th><th>操作</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td><strong>{{entry.name}}</strong><br><small>Asset #{{entry.assetId}}</small></td><td>{{catalogKinds[entry.kind]}}<br><small>{{[entry.database,entry.schema,entry.table,entry.field].filter(Boolean).join(' / ')||entry.parentRef}}</small></td><td>{{entry.source}} · {{entry.current?'当前批次':'来源过期 / 未观察'}}<br><small>{{formatDate(entry.observedAt)}}</small></td><td>{{entry.confirmedMetadata.business||entry.metadata.business||'待补充'}}<br><small>{{entry.confirmedMetadata.ownerTeam||entry.metadata.ownerTeam||'责任团队待确认'}}</small><p v-if="Object.keys(entry.conflicts).length">存在来源属性冲突</p></td><td>{{assetCategoryLabels[entry.category]||'待分类'}} · {{assetBusinessLevelLabels[entry.businessLevel]||'待分级'}}<br><small>{{assetStatutoryCategoryLabels[entry.statutoryCategory]||'待认定'}}</small></td><td><button class="button" @click="choose(entry)">详情 / 历史</button><br><a :href="`#/${encodeURIComponent(workspace.slug)}/classification`">分类确认</a></td></tr><tr v-if="!entries.length"><td colspan="6">暂无目录资产。成功采集或导入 CMDB 后会出现在这里。</td></tr></tbody></table></div>
<section v-if="selected" class="catalog-card"><header class="page-header"><h2>{{selected.name}} · Asset #{{selected.assetId}}</h2><button class="button" @click="selected=null">关闭详情</button></header><p>{{selected.source}} / {{selected.sourceRef}} · 目录修订 v{{selected.revision}}</p><form class="metadata-form" @submit.prevent="save"><label v-for="(label,key) in catalogMetadataFields" :key="key">{{label}}<input v-model="metadata[key]" :readonly="!editable" maxlength="1000"></label><button v-if="editable" class="button primary" :disabled="busy">确认业务属性</button></form><details open><summary>自动来源元数据与规则命中依据</summary><pre>{{JSON.stringify(selected.metadata,null,2)}}</pre></details><details v-if="Object.keys(selected.conflicts).length" open><summary>来源冲突（人工确认已保留）</summary><pre>{{JSON.stringify(selected.conflicts,null,2)}}</pre></details><h3>最近50次修订</h3><details v-for="h in history" :key="h.revision"><summary>v{{h.revision}} · {{h.origin}} · {{formatDate(h.createdAt)}}</summary><pre>{{JSON.stringify(h.metadata,null,2)}}</pre></details></section>
</section></template>
<style scoped>.catalog-page{display:grid;gap:1.2rem}.catalog-card{border:1px solid #dce3df;border-radius:12px;padding:1.2rem;background:var(--surface,#fff)}.catalog-stats,.catalog-filters{display:flex;gap:1.2rem;flex-wrap:wrap;align-items:end}.catalog-stats span{padding:1rem;background:var(--surface,#fff);border:1px solid #dce3df;border-radius:8px}.catalog-filters label,.metadata-form label{display:grid;gap:.4rem}.metadata-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1rem;margin:1rem 0}input,select,textarea{max-width:100%;padding:.6rem;border:1px solid #ccd3d1;border-radius:6px}textarea{display:block;width:100%;margin:1rem 0;font-family:monospace}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:.8rem;border-bottom:1px solid #e2e7e4}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.85rem}details{margin:.8rem 0}</style>
